import { verifyAdmin, getSession } from '@/app/lib/auth'
import { forbidden } from 'next/navigation'

export default async function AdminPage() {
  const adminCheck = await verifyAdmin()
  const directSession = await getSession()

  // Prefer whichever session has admin role, or directSession, or adminCheck.session
  const session =
    (adminCheck?.session?.role === 'admin' ? adminCheck.session : null) ??
    (directSession?.role === 'admin' ? directSession : null) ??
    adminCheck?.session ??
    directSession

  const isAdmin =
    (adminCheck?.isAdmin && adminCheck?.session?.role === 'admin') ||
    session?.role === 'admin'

  if (!isAdmin || !session || session.role !== 'admin') {
    forbidden()
  }

  return (
    <main style={{ padding: '2rem', fontFamily: 'system-ui, sans-serif' }}>
      <h1>Admin Dashboard</h1>
      <p>Welcome, {session.name}!</p>
      <p>You have access to the admin area.</p>
    </main>
  )
}

