import { describe, it, expect, vi, beforeEach } from 'vitest'
import React from 'react'
import AdminPage from './page'
import Forbidden from '../forbidden'
import * as auth from '../lib/auth'

describe('Admin Page and Auth Boundary', () => {
  beforeEach(() => {
    vi.restoreAllMocks()
    process.env.__NEXT_EXPERIMENTAL_AUTH_INTERRUPTS = 'true'
  })

  it('calls forbidden() when user has non-admin role', async () => {
    vi.spyOn(auth, 'getSession').mockResolvedValue({
      userId: '123',
      role: 'user',
      name: 'Regular User',
    })
    vi.spyOn(auth, 'verifyAdmin').mockResolvedValue({
      isAdmin: false,
      session: {
        userId: '123',
        role: 'user',
        name: 'Regular User',
      },
    })

    await expect(AdminPage()).rejects.toThrow('NEXT_HTTP_ERROR_FALLBACK;403')
  })

  it('calls forbidden() when session is null', async () => {
    vi.spyOn(auth, 'getSession').mockResolvedValue(null)
    vi.spyOn(auth, 'verifyAdmin').mockResolvedValue({
      isAdmin: false,
      session: null,
    })

    await expect(AdminPage()).rejects.toThrow('NEXT_HTTP_ERROR_FALLBACK;403')
  })

  it('renders admin dashboard when user has admin role', async () => {
    vi.spyOn(auth, 'getSession').mockResolvedValue({
      userId: '456',
      role: 'admin',
      name: 'Admin User',
    })
    vi.spyOn(auth, 'verifyAdmin').mockResolvedValue({
      isAdmin: true,
      session: {
        userId: '456',
        role: 'admin',
        name: 'Admin User',
      },
    })

    const result = await AdminPage()
    expect(result).toBeDefined()
    expect(result.type).toBe('main')
  })

  it('renders Forbidden error component with proper message and home link', () => {
    const result = Forbidden()
    expect(result).toBeDefined()
  })
})

